


-- Designate one manager per department (their manager_id stays NULL, i.e. top of their reporting line),
-- and point every other employee in that department to them.
UPDATE employee SET manager_id = 'e0000007-e007-e007-e007-e00000070007'
WHERE dept_id = 'd1a1a1a1-1111-1111-1111-111111111111' AND id <> 'e0000007-e007-e007-e007-e00000070007';

UPDATE employee SET manager_id = 'e0000005-e005-e005-e005-e00000050005'
WHERE dept_id = 'd2a2a2a2-2222-2222-2222-222222222222' AND id <> 'e0000005-e005-e005-e005-e00000050005';

UPDATE employee SET manager_id = 'e0000006-e006-e006-e006-e00000060006'
WHERE dept_id = 'd3a3a3a3-3333-3333-3333-333333333333' AND id <> 'e0000006-e006-e006-e006-e00000060006';


